import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Troubleshooting Laravel SaaS Kits","description":"Fixes for common problems: Vite manifest errors, tenant subdomains, queued emails, stale translations or types, tenant database clashes and 403 errors.","frontmatter":{"title":"Troubleshooting Laravel SaaS Kits","description":"Fixes for common problems: Vite manifest errors, tenant subdomains, queued emails, stale translations or types, tenant database clashes and 403 errors.","head":[["link",{"rel":"canonical","href":"https://saas-laravel.com/docs/reference/troubleshooting.html"}],["meta",{"property":"og:title","content":"Troubleshooting Laravel SaaS Kits"}],["meta",{"property":"og:description","content":"Fixes for common problems: Vite manifest errors, tenant subdomains, queued emails, stale translations or types, tenant database clashes and 403 errors."}],["meta",{"property":"og:url","content":"https://saas-laravel.com/docs/reference/troubleshooting.html"}],["meta",{"name":"twitter:title","content":"Troubleshooting Laravel SaaS Kits"}],["meta",{"name":"twitter:description","content":"Fixes for common problems: Vite manifest errors, tenant subdomains, queued emails, stale translations or types, tenant database clashes and 403 errors."}]]},"headers":[],"relativePath":"docs/reference/troubleshooting.md","filePath":"docs/reference/troubleshooting.md","lastUpdated":1790486087000}'),s={name:"docs/reference/troubleshooting.md"};function r(d,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Symptom</th><th>Usual cause</th></tr></thead><tbody><tr><td>Vite manifest error</td><td>Frontend not built / dev server not running</td></tr><tr><td>404 on <code>localhost</code> or <code>127.0.0.1</code></td><td>App opened on a host that is not <code>APP_DOMAIN</code></td></tr><tr><td>Tenant subdomain does not load</td><td>No wildcard DNS or site link</td></tr><tr><td>Emails not sent</td><td>No queue worker, or <code>MAIL_MAILER=log</code></td></tr><tr><td>Stale translations, routes or types</td><td>Generated files not regenerated</td></tr><tr><td>403 after registering</td><td>Self-registered users have no role</td></tr></tbody></table><h2 id="unable-to-locate-file-in-vite-manifest" tabindex="-1"><code>Unable to locate file in Vite manifest</code> <a class="header-anchor" href="#unable-to-locate-file-in-vite-manifest" aria-label="Permalink to &quot;`Unable to locate file in Vite manifest`&quot;">​</a></h2><p>The frontend has not been built, or the dev server is not running. Run <code>npm run dev</code> (or <code>composer dev</code>) during development, or <code>npm run build</code> for a production-like build.</p><h2 id="the-app-shows-404-on-127-0-0-1-8000-or-localhost" tabindex="-1">The app shows 404 on <code>127.0.0.1:8000</code> or <code>localhost</code> <a class="header-anchor" href="#the-app-shows-404-on-127-0-0-1-8000-or-localhost" aria-label="Permalink to &quot;The app shows 404 on `127.0.0.1:8000` or `localhost`&quot;">​</a></h2><p>Only <code>APP_DOMAIN</code> is a central domain; any other host is treated as a tenant and unknown tenants return 404. Open the app at <code>APP_URL</code> (e.g. <code>http://vue.test</code>), not the address printed by <code>php artisan serve</code>.</p><h2 id="tenant-subdomain-does-not-load" tabindex="-1">Tenant subdomain does not load <a class="header-anchor" href="#tenant-subdomain-does-not-load" aria-label="Permalink to &quot;Tenant subdomain does not load&quot;">​</a></h2><ul><li>The tenant domain must resolve to the app. With Herd, link the site with the name matching <code>APP_DOMAIN</code> (<code>herd link vue</code> for <code>vue.test</code>); all <code>*.vue.test</code> subdomains then work.</li><li>Without Herd you need wildcard DNS (e.g. dnsmasq) and a web server that serves <code>*.APP_DOMAIN</code> from <code>public/</code>. A plain <code>/etc/hosts</code> file cannot do wildcards.</li><li>In production add a <code>*.your-domain.com</code> DNS record and a wildcard TLS certificate.</li><li>Check the domain exists: <code>php artisan tenants:list</code>.</li></ul><h2 id="invitation-or-password-reset-emails-are-not-sent" tabindex="-1">Invitation or password reset emails are not sent <a class="header-anchor" href="#invitation-or-password-reset-emails-are-not-sent" aria-label="Permalink to &quot;Invitation or password reset emails are not sent&quot;">​</a></h2><p>These notifications are queued (<code>QUEUE_CONNECTION=database</code>).</p><ol><li>Run a worker: <code>composer dev</code> (includes <code>queue:listen</code>) or <code>php artisan queue:work</code>.</li><li>Keep <code>DB_QUEUE_CONNECTION</code> unset (it falls back to <code>DB_CONNECTION</code>) so jobs from tenants land in the central <code>jobs</code> table where the worker looks.</li><li>With <code>MAIL_MAILER=log</code> emails are written to <code>storage/logs/laravel.log</code>, not delivered. Configure SMTP to send them.</li><li>Check <code>php artisan queue:failed</code>.</li></ol><h2 id="translations-do-not-update-in-the-ui" tabindex="-1">Translations do not update in the UI <a class="header-anchor" href="#translations-do-not-update-in-the-ui" aria-label="Permalink to &quot;Translations do not update in the UI&quot;">​</a></h2><p>The frontend reads the generated JSON in <code>resources/js/lang</code>, not <code>lang/</code> directly. Run <code>php artisan erag:generate-lang</code> after changing <code>lang/</code>.</p><p>Also check you import the helper from the framework subpath (<code>@erag/lang-sync-inertia/vue</code>, <code>/react</code>, <code>/svelte</code>).</p><h2 id="route-functions-or-types-are-outdated-typescript-errors-after-backend-changes" tabindex="-1">Route functions or types are outdated / TypeScript errors after backend changes <a class="header-anchor" href="#route-functions-or-types-are-outdated-typescript-errors-after-backend-changes" aria-label="Permalink to &quot;Route functions or types are outdated / TypeScript errors after backend changes&quot;">​</a></h2><p>Regenerate the generated files:</p><table tabindex="0"><thead><tr><th>Command</th><th>Regenerates</th></tr></thead><tbody><tr><td><code>php artisan wayfinder:generate --with-form</code></td><td><code>@/routes</code>, <code>@/actions</code></td></tr><tr><td><code>php artisan typescript:transform</code></td><td><code>resources/js/types</code></td></tr></tbody></table><p>Restart <code>npm run dev</code> if the editor still shows stale types.</p><h2 id="creating-a-tenant-fails-with-a-database-error" tabindex="-1">Creating a tenant fails with a database error <a class="header-anchor" href="#creating-a-tenant-fails-with-a-database-error" aria-label="Permalink to &quot;Creating a tenant fails with a database error&quot;">​</a></h2><ul><li><strong>Access denied / cannot create database</strong>: the DB user needs <code>CREATE DATABASE</code> (and <code>DROP DATABASE</code> to delete tenants).</li><li><strong>Database exists</strong>: another app on the same MySQL server already created <code>tenant1</code>, or a previous <code>migrate:fresh</code> left tenant databases behind. Drop the old databases, or use a unique tenant DB prefix: <code>TENANCY_DB_PREFIX</code> in the React kit, <code>&#39;prefix&#39;</code> in <code>config/tenancy.php</code> in Vue and Svelte. See <a href="/docs/core/database.html#tenant-database-naming">Database</a>.</li></ul><h2 id="new-tenant-migration-did-not-run" tabindex="-1">New tenant migration did not run <a class="header-anchor" href="#new-tenant-migration-did-not-run" aria-label="Permalink to &quot;New tenant migration did not run&quot;">​</a></h2><p>Tenant migrations belong in <code>database/migrations/tenant</code> and run with <code>php artisan tenants:migrate</code>, not <code>php artisan migrate</code>.</p><h2 id="_403-right-after-registering" tabindex="-1">403 right after registering <a class="header-anchor" href="#_403-right-after-registering" aria-label="Permalink to &quot;403 right after registering&quot;">​</a></h2><p>Self-registered users get no role and no permissions, and <code>/dashboard</code> requires <code>View Analytics Dashboard</code> (central) or <code>View Tenant Dashboard</code> (tenant). Assign a role or permissions from <strong>Users</strong>, or assign a default role in <code>Modules\\Auth\\Actions\\CreateNewUser</code>. See <a href="/docs/core/authentication.html#registration-and-permissions">Authentication</a>.</p><h2 id="a-menu-item-is-missing" tabindex="-1">A menu item is missing <a class="header-anchor" href="#a-menu-item-is-missing" aria-label="Permalink to &quot;A menu item is missing&quot;">​</a></h2><p>Menus are filtered by their <code>permission</code> column. Check the user has that permission, or that the item exists in the current context&#39;s <code>menus</code> table (central and tenant menus are separate). <strong>Setup → Menus → Reset</strong> restores the seeded defaults.</p><h2 id="changes-to-config-permissions-have-no-effect" tabindex="-1">Changes to <code>config/permissions</code> have no effect <a class="header-anchor" href="#changes-to-config-permissions-have-no-effect" aria-label="Permalink to &quot;Changes to `config/permissions` have no effect&quot;">​</a></h2><p>Permissions must exist in the database. Run <code>php artisan db:seed --class=PermissionSeeder</code> (central) and <code>php artisan tenants:seed --class=&quot;Database\\Seeders\\PermissionSeeder&quot;</code> (tenants), then assign them. spatie caches permissions for 24 hours; the seeders clear the cache, otherwise run <code>php artisan permission:cache-reset</code>.</p><h2 id="passkeys-do-not-work-locally" tabindex="-1">Passkeys do not work locally <a class="header-anchor" href="#passkeys-do-not-work-locally" aria-label="Permalink to &quot;Passkeys do not work locally&quot;">​</a></h2><p>WebAuthn needs a secure origin (HTTPS). Secure the site (for example <code>herd secure vue</code>) and use an <code>https://</code> <code>APP_URL</code>. The React and Svelte <code>.env.example</code> files already use <code>https://</code>; the Vue one uses <code>http://vue.test</code>.</p><h2 id="a-tenant-shows-the-maintenance-or-suspended-page" tabindex="-1">A tenant shows the maintenance or suspended page <a class="header-anchor" href="#a-tenant-shows-the-maintenance-or-suspended-page" aria-label="Permalink to &quot;A tenant shows the maintenance or suspended page&quot;">​</a></h2><ul><li>Maintenance: <strong>Setup → Tenant Settings</strong> on the central domain, or use the bypass link / IP allow list.</li><li>Suspended: set the tenant&#39;s Workspace status back to Active.</li></ul><p>See <a href="/docs/core/maintenance-and-suspension.html">Maintenance &amp; suspension</a>.</p><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p>Open an issue on your kit&#39;s GitHub repository with the error, the steps to reproduce and your PHP/Node versions.</p>',35)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
